  patchy:{robe:'#7a8a5a',hat:'hood',wrap:'#d9cfb6',sash:'#a5683a',skin:'#c98f63',wide:1.04},
  bald:{robe:'#b0623e',hat:'bare',skin:'#d2a07a',sash:'#5a4a3a',wide:1.1,tall:.94},
