function birds(x,y,n,seed,c='#4a3f5c',dx=160,d=26){const r=rng(seed);let s='';for(let i=0;i<n;i++){const bx=x+r()*70-35,by=y+r()*34-17,sc=(.7+r()*.6).toFixed(2),du=(.45+r()*.3).toFixed(2);s+=`<g transform="translate(${bx.toFixed(1)} ${by.toFixed(1)}) scale(${sc})"><path d="M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0" stroke="${c}" stroke-width="1.8" fill="none" stroke-linecap="round"><animate attributeName="d" values="M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0;M-7 -3 Q-3.5 2 0 0 Q3.5 2 7 -3;M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0" dur="${du}s" repeatCount="indefinite"/></path></g>`}return `<g>${drift(dx,-12,d)}${s}</g>`}
