function jar(u,x,y,s=1,o={}){const c=o.c||'#c4673c';const gold=o.gold?`<path d="M-11 -41 Q0 -55 11 -41Z" fill="#ffcc3d"/>${[[-6,-44],[3,-47],[-1,-50],[6,-42],[-8,-41]].map(([a,b])=>`<ellipse cx="${a}" cy="${b}" rx="4.4" ry="2" fill="#ffdc5c" stroke="#c9961f" stroke-width=".7"/>`).join('')}`:'';
  return `<g transform="translate(${x} ${y}) scale(${s})">${o.glow?`<circle cx="0" cy="-34" r="60" fill="url(#${u}gold)"><animate attributeName="opacity" values=".65;1;.65" dur="2.8s" repeatCount="indefinite"/></circle>`:''}<path d="M-13 0 Q-25 -18 -14 -33 L-9 -38 L9 -38 L14 -33 Q25 -18 13 0Z" fill="${c}"/><path d="M-19 -21 Q0 -14 19 -21" stroke="${shade(c,.3)}" stroke-width="3" fill="none"/><path d="M-18 -14 Q0 -8 18 -14" stroke="${shade(c,-.25)}" stroke-width="1.5" fill="none" stroke-dasharray="3 3"/><path d="M-8 -30 Q-12 -20 -8 -10" stroke="${shade(c,.45)}" stroke-width="2.5" fill="none" stroke-linecap="round" opacity=".6"/><rect x="-11" y="-42" width="22" height="5" rx="2" fill="${shade(c,-.22)}"/>${gold}</g>`}
const sparkle=(x,y,r,d=0,c='#fff7d1')=>`<path transform="translate(${x} ${y})" d="M0 ${-r} L${r*.22} ${-r*.22} L${r} 0 L${r*.22} ${r*.22} L0 ${r} L${-r*.22} ${r*.22} L${-r} 0 L${-r*.22} ${-r*.22}Z" fill="${c}"><animate attributeName="opacity" values="0;1;0" dur="2.4s" begin="${d}s" repeatCount="indefinite"/></path>`;
function sparkles(n,seed,x1,y1,x2,y2,c){const r=rng(seed);let s='';for(let i=0;i<n;i++)s+=sparkle((x1+r()*(x2-x1)).toFixed(1),(y1+r()*(y2-y1)).toFixed(1),(3+r()*5).toFixed(1),(r()*2.4).toFixed(1),c);return s}
function hearts(n,x,y,seed,c='#ef7f8f'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const hx=x+r()*50-25,d=(3+r()*2).toFixed(1),b=(-r()*4).toFixed(1),sc=(.9+r()*.8).toFixed(2);s+=`<g><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*20-10).toFixed(0)} -60" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;0" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><path transform="translate(${hx.toFixed(1)} ${y}) scale(${sc})" d="M0 3 C-6 -2 -6 -8 -2.5 -8 C-1 -8 0 -7 0 -6 C0 -7 1 -8 2.5 -8 C6 -8 6 -2 0 3Z" fill="${c}"/></g>`}return s}
function motes(n,seed,y1,y2,c='#ffe08a'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const x=r()*400,y=y1+r()*(y2-y1),d=(4+r()*4).toFixed(1);s+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(1+r()*1.6).toFixed(1)}" fill="${c}"><animate attributeName="opacity" values="0;1;0" dur="${d}s" begin="${(-r()*4).toFixed(1)}s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*20-10).toFixed(0)} -18;0 0" dur="${d}s" repeatCount="indefinite"/></circle>`}return s}
const shoe=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-9 0 L-9 -11 Q-9 -15 -5 -15 L1 -15 L1 -6 Q9 -6 13 -2 L13 0Z" fill="#7b4b2a"/><ellipse cx="-4" cy="-15" rx="5" ry="1.8" fill="#6fc3e6"/><path d="M-9 -2 L13 -2" stroke="#5c3720" stroke-width="1.5"/></g>`;
const heat=(x,y)=>`<path d="M${x} ${y} q5 -5 10 0 t10 0 t10 0" stroke="#fff6e0" stroke-width="1.6" fill="none" opacity=".0"><animate attributeName="opacity" values="0;.7;0" dur="2.6s" begin="${(x%7)/3}s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 0;0 -10" dur="2.6s" begin="${(x%7)/3}s" repeatCount="indefinite"/></path>`;
function rays(cx,cy,n,len,c,op=.35,a0=-160,a1=-20){let s='';for(let i=0;i<n;i++){const a=(a0+i*((a1-a0)/(n-1)))*Math.PI/180,a2=a+.07;s+=`<polygon points="${cx},${cy} ${(cx+Math.cos(a)*len).toFixed(1)},${(cy-Math.sin(a)*-len).toFixed(1)} ${(cx+Math.cos(a2)*len).toFixed(1)},${(cy-Math.sin(a2)*-len).toFixed(1)}" fill="${c}"/>`}return `<g opacity="${op}"><animate attributeName="opacity" values="${op};${op*.45};${op}" dur="5s" repeatCount="indefinite"/>${s}</g>`}
function lanternString(y0,sag,n,cols,W=400){let s=`<path d="M-10 ${y0} Q${W/2} ${y0+sag*2} ${W+10} ${y0}" stroke="#d9b56b" stroke-width="1.2" fill="none"/>`;for(let i=1;i<=n;i++){const t=i/(n+1),x=-10+(W+20)*t,y=(1-t)*(1-t)*y0+2*(1-t)*t*(y0+sag*2)+t*t*y0,c=cols[i%cols.length],len=8+(i%3)*7;s+=`<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><g>${rot(-6,6,0,0,3+i%3)}<line x1="0" y1="0" x2="0" y2="${len}" stroke="#d9b56b" stroke-width="1"/><circle cx="0" cy="${len+13}" r="17" fill="${c}" opacity=".22"/><path d="M-5 ${len} L5 ${len} L7.5 ${len+7} L4.5 ${len+20} L-4.5 ${len+20} L-7.5 ${len+7}Z" fill="${c}"/><path d="M-2 ${len+8} L2 ${len+8} L2 ${len+17} L-2 ${len+17}Z" fill="#fff6cf" opacity=".95"/><rect x="-3" y="${len+20}" width="6" height="3" fill="#b38a3a"/><path d="M-2 ${len} Q0 ${len-5} 2 ${len}" fill="${c}"/></g></g>`}return s}
function starPts(r1,r2,n=8){const p=[];for(let i=0;i<n*2;i++){const a=Math.PI*i/n-Math.PI/2,r=i%2?r2:r1;p.push((Math.cos(a)*r).toFixed(2)+','+(Math.sin(a)*r).toFixed(2))}return p.join(' ')}
function valueIcon(icon,u){
  if(icon==='paw')return `<g fill="#5a3410"><ellipse cx="0" cy="8" rx="13" ry="11"/><ellipse cx="-15" cy="-7" rx="5.5" ry="7" transform="rotate(-20 -15 -7)"/><ellipse cx="-5" cy="-15" rx="5.5" ry="7.5"/><ellipse cx="6" cy="-15" rx="5.5" ry="7.5"/><ellipse cx="16" cy="-6" rx="5.5" ry="7" transform="rotate(20 16 -6)"/></g>`;
  if(icon==='ant')return ant(-2,12,2.1,{c:'#5a3410'});
  if(icon==='hands')return `<g fill="#5a3410">${[-1,1].map(m=>`<g transform="scale(${m} 1) translate(10 4) rotate(-14)"><rect x="-8" y="-4" width="16" height="20" rx="7"/>${[-7.5,-3,1.5,6].map((fx,i)=>`<rect x="${fx-.5}" y="${-17+Math.abs(i-1.5)*2}" width="4.4" height="16" rx="2.2"/>`).join('')}<rect x="-12" y="-1" width="4.4" height="11" rx="2.2" transform="rotate(-30 -10 8)"/></g>`).join('')}</g>`;
  if(icon==='fish')return `<g fill="#5a3410"><path d="M-20 2 Q-4 -18 14 -8 Q20 -4 22 2 Q20 7 14 10 Q-4 20 -20 2Z"/><path d="M-17 2 L-31 -11 L-27 2 L-31 15Z"/></g><circle cx="11" cy="-1" r="2.6" fill="#ffe7a6"/>`;
  if(icon==='sheep')return `<g fill="#5a3410">${[[-12,-2,10],[0,-8,11],[12,-2,10],[-6,8,10],[8,8,10]].map(([a,b,r])=>`<circle cx="${a}" cy="${b}" r="${r}"/>`).join('')}<rect x="-12" y="12" width="5" height="12" rx="2"/><rect x="7" y="12" width="5" height="12" rx="2"/><ellipse cx="22" cy="-4" rx="9" ry="11" transform="rotate(-20 22 -4)"/></g><circle cx="25" cy="-6" r="2.4" fill="#ffe7a6"/>`;
  if(icon==='spring')return `<path d="M0 -28 Q17 -6 17 5 Q17 20 0 20 Q-17 20 -17 5 Q-17 -6 0 -28Z" fill="#5a3410"/><path d="M-7 3 Q-7 11 1 13" stroke="#ffe08a" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M-28 24 Q0 33 28 24" stroke="#5a3410" stroke-width="3.5" fill="none" stroke-linecap="round"/>`;
  if(icon==='lamp')return `<g fill="#5a3410"><path d="M-20 4 Q-20 -8 0 -8 Q14 -8 18 -4 L30 -8 Q30 0 20 6 Q12 13 0 13 Q-20 13 -20 4Z"/><path d="M-19 0 Q-31 -2 -29 8 Q-27 14 -18 9" stroke="#5a3410" stroke-width="4" fill="none"/><rect x="-10" y="12" width="20" height="5" rx="2"/></g><ellipse cx="-2" cy="-7" rx="7" ry="2" fill="#ffe7a6" opacity=".6"/><path d="M28 -9 Q20 -18 28 -32 Q36 -18 28 -9Z" fill="#c8841c"/><path d="M28 -12 Q24.5 -17 28 -25 Q31.5 -17 28 -12Z" fill="#fff4c9"/>`;
  if(icon==='jar')return jar(u,0,22,.95,{c:'#8a3f1e',gold:true});
  return `<path d="M0 20C-22 4-24-14-12-20C-4-24 0-16 0-12C0-16 4-24 12-20C24-14 22 4 0 20Z" fill="#5a3410"/>`;
}
function badge(u,icon,size=1){return `<g transform="scale(${size})"><polygon points="${starPts(46,37)}" fill="url(#${u}bdg)" stroke="#fff3c4" stroke-width="2"/><polygon points="${starPts(40,32)}" fill="none" stroke="#a8701a" stroke-width="1.2" opacity=".7"/><circle r="27" fill="#ffe7a6" stroke="#c98a1f" stroke-width="1.5"/>${valueIcon(icon,u)}</g>`}
function badgeSvg(icon){const u='b'+(UID++)+'_';return `<svg viewBox="-50 -50 100 100" aria-hidden="true"><defs>${lg(u+'bdg',['#ffe08a','#f2b84b','#c8841c'])}${rg(u+'gold','#ffd451',.9)}</defs>${badge(u,icon)}</svg>`}

/* Camels for the travellers from Yemen: kawaii eye and blush, as with the other animals. */
function camel(x,y,s=1,o={}){
  const c=o.c||'#d6a46a',d=shade(c,-.25),l=shade(c,.25),walk=o.walk;
  const leg=(lx,back,i)=>`<g>${walk?rot(back?8:-8,back?-8:8,lx+2,-40,1.4):''}<path d="M${lx} -40 L${lx-1} -3 L${lx+5} -3 L${lx+5} -40Z" fill="${back?d:c}"/><ellipse cx="${lx+2.5}" cy="-2" rx="4.4" ry="2.2" fill="${shade(c,-.4)}"/></g>`;
  const load=o.load?`<path d="M-20 -58 Q-4 -66 14 -58 L16 -42 Q-2 -36 -22 -42Z" fill="${o.load}"/><path d="M-21 -44 Q-3 -38 15 -44" stroke="#fff3c4" stroke-width="2" fill="none" stroke-dasharray="3 3"/>${[-18,-8,2,12].map(t=>`<line x1="${t}" y1="-40" x2="${t}" y2="-33" stroke="${o.load}" stroke-width="2"/>`).join('')}`:'';
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})"><ellipse cx="0" cy="0" rx="32" ry="3.6" fill="#000" opacity=".14"/>${leg(-22,1)}${leg(10,1)}${leg(-14)}${leg(18)}<g>${walk?bob(-1.5,.7):''}<path d="M-30 -44 Q-34 -58 -20 -60 Q-8 -86 6 -62 Q20 -64 28 -52 Q30 -40 18 -38 L-22 -38 Q-30 -38 -30 -44Z" fill="${c}"/>${o.baby?`<path d="M-24 -40 Q-6 -24 16 -40Z" fill="${c}"/><path d="M-18 -33 Q-4 -26 10 -34" stroke="${d}" stroke-width="1.4" fill="none" opacity=".6"/>`:''}<path d="M-12 -74 Q-4 -80 2 -70" stroke="${l}" stroke-width="2.4" fill="none" opacity=".7"/><path d="M-30 -46 Q-38 -42 -36 -30" stroke="${c}" stroke-width="3" fill="none" stroke-linecap="round">${rot(-8,8,-30,-46,2)}</path>${load}<path d="M22 -54 Q34 -60 34 -78 Q34 -88 40 -90 L46 -86 Q42 -80 42 -72 Q42 -54 28 -44Z" fill="${c}"/><ellipse cx="46" cy="-86" rx="11" ry="6.5" fill="${c}"/><ellipse cx="53" cy="-83" rx="5" ry="4" fill="${l}"/><path d="M38 -92 q-3 -5 1 -6 q2 2 1 6Z" fill="${d}"/><ellipse cx="45" cy="-88" rx="2.2" ry="2.8" fill="#2a1d17"/><circle cx="45.8" cy="-89" r=".8" fill="#fff"/><ellipse cx="47" cy="-83" rx="2.4" ry="1.3" fill="#f28a8a" opacity=".55"/><path d="M53 -81 q2 1 3.5 0" stroke="#2a1d17" stroke-width="1" fill="none" stroke-linecap="round"/></g></g>`;
}
/* Tall mud-brick tower houses of Yemen, with white trim and arched windows. */
function towerHouse(x,y,s=1,c='#b8794e',h=90){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-20" y="${-h}" width="40" height="${h}" fill="${c}"/><rect x="-20" y="${-h}" width="9" height="${h}" fill="${shade(c,-.15)}"/><path d="M-22 ${-h} h44 v-5 h-6 v-4 h-6 v4 h-8 v-4 h-6 v4 h-8 v-4 h-6 v4 h-4Z" fill="${shade(c,-.1)}"/>${[...Array(Math.floor(h/26))].map((_,i)=>{const wy=-h+12+i*26;return `<path d="M-23 ${wy+16} h46" stroke="#fff6e6" stroke-width="1.6"/>`+[-9,7].map(wx=>`<path d="M${wx-4} ${wy+10} V${wy+4} A4 4 0 0 1 ${wx+4} ${wy+4} V${wy+10}Z" fill="#4a2e1e"/><path d="M${wx-5.5} ${wy+4} A5.5 5.5 0 0 1 ${wx+5.5} ${wy+4}" stroke="#fff6e6" stroke-width="1.6" fill="none"/>`).join('')}).join('')}<path d="M-5 0 V-12 A5 5 0 0 1 5 -12 V0Z" fill="#4a2e1e"/></g>`}
function mudHouse(x,y,s=1,c='#d9b48a'){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-18" y="-24" width="36" height="24" rx="2" fill="${c}"/><rect x="-18" y="-24" width="8" height="24" fill="${shade(c,-.14)}"/><path d="M-20 -24 h40" stroke="${shade(c,-.25)}" stroke-width="3"/>${[-12,-4,4,12].map(t=>`<line x1="${t}" y1="-26" x2="${t+1}" y2="-22" stroke="#6b4a32" stroke-width="1.6"/>`).join('')}<path d="M-4 0 V-10 A4 4 0 0 1 4 -10 V0Z" fill="#5a3b28"/><rect x="8" y="-17" width="5" height="5" fill="${o_win}"/></g>`}
const scroll=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-5" y="-9" width="10" height="18" rx="2" fill="#fbf0d6" stroke="#b08a52" stroke-width="1"/><rect x="-6.5" y="-11" width="13" height="4" rx="2" fill="#d9b56b"/><rect x="-6.5" y="7" width="13" height="4" rx="2" fill="#d9b56b"/><path d="M-2.5 -3 h5 M-2.5 0 h5 M-2.5 3 h4" stroke="#8a6a45" stroke-width=".8"/></g>`;

/* Prophets are never pictured: Prophets Yunus and Ayyub are shown only as a soft, warm light (dim: paler, for Ayyub's illness). */
function nur(u,x,y,s=1,dim){return `<g transform="translate(${x} ${y}) scale(${s})"${dim?' opacity=".72"':''}><circle r="34" fill="url(#${u}nur)"><animate attributeName="r" values="28;38;28" dur="4s" repeatCount="indefinite"/></circle><circle r="8" fill="#fffbe6" opacity=".95"/>${sparkle(0,0,16,0,'#fffbe6')}${sparkle(14,-14,5,1.2,'#fff3c4')}${sparkle(-13,10,4,.6,'#fff3c4')}</g>`}
/* The great fish, a gentle whale-like giant with a kawaii eye and blush, like the other animals. */
function bigFish(x,y,s=1,o={}){
  const c=o.c||'#4f86c6',d=shade(c,-.3),l=shade(c,.32),bel=o.belly||'#e6f1f7',ln=o.line||'#23324a',happy=o.mood==='happy';
  const tail=`<g>${rot(-8,8,-100,0,o.calm?3.2:1.6)}<path d="M-100 -4 Q-128 -38 -152 -52 Q-140 -12 -152 32 Q-128 22 -100 6Z" fill="${c}" stroke="${ln}" stroke-width="1.4" stroke-linejoin="round"/><path d="M-106 -6 Q-128 -26 -144 -40" stroke="${l}" stroke-width="2" fill="none" opacity=".6"/><path d="M-100 4 Q-124 16 -146 26" stroke="${d}" stroke-width="2" fill="none" opacity=".6"/></g>`;
  const fin=`<g>${rot(-10,12,8,24,2.2)}<path d="M8 24 Q-6 48 -28 56 Q2 52 24 30Z" fill="${d}" stroke="${ln}" stroke-width="1.1" stroke-linejoin="round"/></g>`;
  const body=`<path d="M-104 0 Q-96 -54 -10 -62 Q70 -66 112 -24 Q124 -8 120 6 Q110 44 20 50 Q-70 54 -104 0Z" fill="${c}" stroke="${ln}" stroke-width="1.4" stroke-linejoin="round"/>`+
    `<path d="M-104 0 Q-96 -54 -10 -62 Q-66 -40 -84 6Z" fill="${d}" opacity=".45"/>`+
    `<path d="M-92 14 Q-40 48 30 46 Q100 40 118 10 Q92 28 30 32 Q-40 34 -92 14Z" fill="${bel}"/>`+
    `<path d="M-56 30 Q10 42 96 26 M-40 38 Q20 46 80 36" stroke="${shade(bel,-.14)}" stroke-width="1.6" fill="none"/>`+
    `<path d="M-60 -48 Q20 -70 98 -34" stroke="${l}" stroke-width="3" fill="none" opacity=".75" stroke-linecap="round"/>`+
    [[-40,-30,5],[-22,-42,3.6],[-6,-28,4.4],[14,-44,3],[-60,-18,3.4]].map(([a,b,r])=>`<circle cx="${a}" cy="${b}" r="${r}" fill="${l}" opacity=".45"/>`).join('');
  const eye=happy?`<path d="M71 -20 q6 -7 12 0" stroke="#1d2233" stroke-width="2.4" fill="none" stroke-linecap="round"/>`
    :`<ellipse cx="78" cy="-18" rx="6.4" ry="8" fill="#1d2233"/><ellipse cx="78" cy="-15" rx="4.2" ry="3" fill="#3b4f7a"/><circle cx="80.4" cy="-21.5" r="2.6" fill="#fff"/><circle cx="76" cy="-13.6" r="1.1" fill="#fff"/>`;
  const mouth=o.open?`<path d="M121 2 L74 12 Q96 32 117 20Z" fill="#6a2a3e" stroke="${ln}" stroke-width="1.2" stroke-linejoin="round"/><path d="M80 17 Q98 25 112 20" stroke="#f28a8a" stroke-width="3" fill="none" stroke-linecap="round"/>`
    :`<path d="M118 8 Q100 18 84 12" stroke="${ln}" stroke-width="1.8" fill="none" stroke-linecap="round"/>`;
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s}) rotate(${o.tilt||0})"><g>${o.still?'':bob(-4,3.2)}${tail}${body}${fin}${eye}<ellipse cx="88" cy="-4" rx="6" ry="3.2" fill="#f28a8a" opacity=".55"/>${mouth}${o.emote?emote(o.emote,64,-80,1.2,o.flip):''}</g></g>`;
}
function fishy(x,y,s=1,c='#ffb36b',flip){return `<g transform="translate(${x} ${y}) scale(${flip?-s:s} ${s})"><g>${bob(-2,1.8)}<path d="M-8 0 L-16 -6 L-15 0 L-16 6Z" fill="${shade(c,-.2)}">${rot(-12,12,-8,0,.6)}</path><ellipse rx="10" ry="6.4" fill="${c}"/><path d="M-6 -5 Q0 -8 6 -5" stroke="${shade(c,.4)}" stroke-width="1.4" fill="none"/><circle cx="4.5" cy="-1.2" r="1.8" fill="#1d2233"/><circle cx="5" cy="-1.8" r=".6" fill="#fff"/><ellipse cx="6" cy="2" rx="1.6" ry=".9" fill="#f28a8a" opacity=".6"/></g></g>`}
function school(x,y,n,seed,c,dx=-120,d=18){const r=rng(seed);let s='';for(let i=0;i<n;i++)s+=fishy((x+r()*60-30).toFixed(1),(y+r()*30-15).toFixed(1),(.6+r()*.4).toFixed(2),c,dx>0);return `<g>${drift(dx,0,d)}${s}</g>`}
function kelp(x,y,h,c,d=4){return `<path d="M${x} ${y} Q${x+10} ${y-h*.25} ${x} ${y-h*.5} T${x} ${y-h}" stroke="${c}" stroke-width="6" fill="none" stroke-linecap="round">${rot(-6,6,x,y,d)}</path>`}
function bubbles(n,seed,x1,x2,y1,y2,c='#dff6ff'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const bx=x1+r()*(x2-x1),by=y1+r()*(y2-y1),d=(3+r()*3).toFixed(1),b=(-r()*5).toFixed(1);s+=`<circle cx="${bx.toFixed(1)}" cy="${by.toFixed(1)}" r="${(1.5+r()*3).toFixed(1)}" fill="none" stroke="${c}" stroke-width="1.2"><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*10-5).toFixed(0)} -70" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;.9;0" dur="${d}s" begin="${b}s" repeatCount="indefinite"/></circle>`}return s}
function rising(n,seed,x,y,spread,h,c='#fff3c4'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const d=(3+r()*3).toFixed(1),b=(-r()*6).toFixed(1);s+=`<circle cx="${(x+r()*spread-spread/2).toFixed(1)}" cy="${y}" r="${(1.2+r()*2).toFixed(1)}" fill="${c}"><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*40-20).toFixed(0)} ${-h}" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;0" dur="${d}s" begin="${b}s" repeatCount="indefinite"/></circle>`}return s}
const waveLines=(n,seed,y1,y2,c='#d6f0ff')=>{const r=rng(seed);let s='';for(let i=0;i<n;i++){const x=r()*380,y=y1+r()*(y2-y1),w=10+r()*16;s+=`<path d="M${x.toFixed(1)} ${y.toFixed(1)} q${(w/2).toFixed(1)} -4 ${w.toFixed(1)} 0" stroke="${c}" stroke-width="1.6" fill="none" stroke-linecap="round">${bob(2,2+r()*2)}</path>`}return s};
/* A busy wooden ship, low in the water: the crowd stands at the rail, sacks piled at each end. */
function ship(x,y,s=1,o={}){const n=o.crowd||10,cols=['#e05a4a','#3f6fa3','#f2b84b','#5b8a4c','#8a4f7d','#2fa59a'],wraps=['#ffffff','#f4ead2','#e8e0d0'],skins=['#c98f63','#a87856','#d2a07a','#b98258'];
  let crowd='';for(let i=0;i<n;i++){const cx=-60+i*(120/(n-1)),cy=-20-(i%2)*2.5,up=o.worry&&i%3===1;crowd+=`<g transform="translate(${cx.toFixed(1)} ${cy})">${up?`<path d="M-3 -9 L-7 -20 M3 -9 L7 -20" stroke="${cols[i%6]}" stroke-width="2.6" stroke-linecap="round"/>`:''}<path d="M-5 0 L-4 -11 Q0 -14 4 -11 L5 0Z" fill="${cols[i%6]}" stroke="#3b2a33" stroke-width=".7"/><circle cy="-16.5" r="5" fill="${skins[i%4]}" stroke="#3b2a33" stroke-width=".7"/><path d="M-5 -17 Q-5 -23 0 -23 Q5 -23 5 -17Z" fill="${wraps[i%3]}"/></g>`}
  const sail=`<rect x="-2" y="-150" width="4" height="130" fill="#6b4a2b"/><path d="M-46 -142 Q0 -150 46 -142 Q54 -106 46 -68 Q0 -62 -46 -68 Q-54 -106 -46 -142Z" fill="#f4ead2" stroke="#3b2a33" stroke-width="1"/><path d="M-46 -142 Q-54 -106 -46 -68 Q-34 -66 -30 -67 Q-38 -106 -30 -145Z" fill="#d9ccb0"/><path d="M-12 -146 Q0 -147 12 -146 L12 -64 Q0 -63 -12 -64Z" fill="#e05a4a" opacity=".85"/><path d="M42 -138 Q50 -106 42 -72" stroke="#fffaf0" stroke-width="2" fill="none"/><path d="M0 -150 L90 -26 M0 -150 L-88 -26" stroke="#8a6a45" stroke-width="1"/>`;
  const cargo=[[-74,-28],[-64,-31],[66,-28],[76,-30],[71,-38]].map(([a,b],i)=>`<ellipse cx="${a}" cy="${b}" rx="8" ry="6.5" fill="${i%2?'#c9a074':'#b38a5e'}" stroke="#3b2a33" stroke-width=".7"/>`).join('');
  const hull=`<path d="M78 -22 Q94 -30 98 -48 Q104 -28 86 -14Z M-78 -22 Q-94 -30 -96 -44 Q-102 -26 -86 -14Z" fill="#8a5a36" stroke="#3b2a33" stroke-width="1"/><path d="M-86 -24 L86 -24 Q82 4 56 12 L-58 12 Q-82 4 -86 -24Z" fill="#8a5a36" stroke="#3b2a33" stroke-width="1.2"/><path d="M-88 -26 L88 -26 L86 -20 L-86 -20Z" fill="#b07a4a" stroke="#3b2a33" stroke-width="1"/><path d="M-82 -10 Q0 -4 82 -10 M-74 2 Q0 8 72 2" stroke="#6b4228" stroke-width="1.4" fill="none"/><path d="M-80 -16 Q0 -12 80 -16" stroke="#d6a36e" stroke-width="1.6" fill="none"/>${[-50,-25,0,25,50].map(cx=>`<circle cx="${cx}" cy="-12" r="3" fill="#5e3b22"/>`).join('')}`;
  const slips=o.slips?[0,1,2,3].map(i=>`<g transform="translate(${-20+i*14} -50)"><g><animateTransform attributeName="transform" type="translate" values="0 0;${-14+i*10} -56" dur="3.2s" begin="${i*.8}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" dur="3.2s" begin="${i*.8}s" repeatCount="indefinite"/><g>${rot(-20,20,0,0,1+i*.2)}<rect x="-6" y="-4" width="12" height="8" rx="1" fill="${i===2?'#fff3c4':'#fffaf0'}" stroke="#b08a52" stroke-width=".7"/><path d="M-3.5 -1 h7 M-3.5 1.5 h5" stroke="#8a6a45" stroke-width=".7"/></g></g></g>`).join(''):'';
  const water=`<path d="M-120 2 Q-60 -4 0 2 T120 2 V20 H-120Z" fill="${o.water||'#3f8fc0'}"/><path d="M-110 4 q10 -4 20 0 M-40 6 q10 -4 20 0 M30 4 q10 -4 20 0 M90 6 q8 -3 16 0" stroke="#d6f0ff" stroke-width="1.6" fill="none" stroke-linecap="round"/>`;
  return `<g transform="translate(${x} ${y}) scale(${s})"><g>${o.rock?rot(-3.5,3.5,0,0,o.rock):''}${sail}${crowd}${cargo}${hull}${slips}</g><g>${bob(2,2.6)}${water}</g></g>`}
/* The gourd plant (yaqtin) that Allah grew over Yunus: broad heart-shaped leaves on an arching vine. */
function gourdVine(x,y,s=1){const leaf=(lx,ly,a,k,c)=>`<g transform="translate(${lx} ${ly}) rotate(${a}) scale(${k})"><g>${rot(-5,5,0,0,3+((lx+ly)%3))}<path d="M0 0 C-16 -6 -18 -26 -7 -28 C-3 -29 0 -25 0 -22 C0 -25 3 -29 7 -28 C18 -26 16 -6 0 0Z" fill="${c}" stroke="#2f5a2a" stroke-width=".9"/><path d="M0 -2 L0 -22 M0 -10 L-7 -18 M0 -10 L7 -18" stroke="${shade(c,.35)}" stroke-width="1.1" fill="none"/><path d="M0 0 C-16 -6 -18 -26 -7 -28 C-12 -18 -8 -8 0 0Z" fill="${shade(c,-.18)}" opacity=".6"/></g></g>`;
  const pts=[];for(let i=0;i<=12;i++){const t=i/12,px=-90+180*t,py=-4*96*t*(1-t);pts.push([px,py])}
  const cols=['#5fa64c','#6fb85a','#4f9a44','#7cc466'];
  const leaves=pts.map(([px,py],i)=>leaf(px,py-6,(i-6)*9,1.2+(i%3)*.15,cols[i%4])).join('')+pts.filter((_,i)=>i%2).map(([px,py],i)=>leaf(px+8,py+14,(i*37)%60-30,.9,cols[(i+1)%4])).join('');
  const gourds=[[-46,-58],[22,-70],[60,-40]].map(([gx,gy])=>`<line x1="${gx}" y1="${gy-16}" x2="${gx}" y2="${gy-6}" stroke="#4f8a3e" stroke-width="1.4"/><ellipse cx="${gx}" cy="${gy}" rx="6.5" ry="9" fill="#cfe39a" stroke="#6a8a3e" stroke-width=".9"/><path d="M${gx-2} ${gy-6} q-2 6 0 11" stroke="#f3f8de" stroke-width="1.6" fill="none"/>`).join('');
  const flowersV=[[-70,-40],[-8,-98],[44,-82],[80,-22]].map(([fx,fy])=>`<g transform="translate(${fx} ${fy})">${[0,72,144,216,288].map(a=>`<ellipse cy="-3" rx="2" ry="3.2" fill="#ffd84a" transform="rotate(${a})"/>`).join('')}<circle r="1.6" fill="#e0912a"/></g>`).join('');
  return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-90 0 Q0 -192 90 0" stroke="#5a7a34" stroke-width="4" fill="none"/><path d="M-90 0 Q-60 -40 -70 -60 M90 0 Q70 -30 80 -56" stroke="#5a7a34" stroke-width="2.4" fill="none"/>${gourds}${leaves}${flowersV}</g>`}
/* Old riverside town: flat-roofed mud houses with a few taller towers. */
function oldTown(y,seed){const r=rng(seed);let s='';[[60,.8],[96,1],[300,.95],[338,.8],[372,.9],[24,.9]].forEach(([tx,k])=>{s+=towerHouse(tx,y-2,.42*k,['#b8794e','#c98a5a','#a86a42'][Math.floor(r()*3)],70+Math.floor(r()*30))});[[130,1],[168,.85],[232,.9],[268,1.05],[200,.75]].forEach(([tx,k])=>{s+=mudHouse(tx,y,k,r()>.5?'#e2c094':'#d9b48a')});return s}
/* A crowd of townspeople in the distance; with raise, every pair of hands is lifted to Allah. */
function crowd(x1,x2,y,n,seed,raise,k=1){const r=rng(seed),cols=['#e05a4a','#3f6fa3','#f2b84b','#5b8a4c','#8a4f7d','#2fa59a','#c98a4e'],wraps=['#ffffff','#f4ead2','#e8e0d0','#efe6f4'];let s='';for(let i=0;i<n;i++){const cx=x1+(x2-x1)*(i+r()*.6)/n,cy=y+(i%3)*3,c=cols[Math.floor(r()*7)];s+=`<g transform="translate(${cx.toFixed(1)} ${cy}) scale(${k})">${raise?`<g>${bob(-1.5,1+r())}<path d="M-3 -9 L-7 -21 M3 -9 L7 -21" stroke="${c}" stroke-width="2.6" stroke-linecap="round"/></g>`:''}<path d="M-5 0 L-4 -11 Q0 -14 4 -11 L5 0Z" fill="${c}" stroke="#3b2a33" stroke-width=".6"/><circle cy="-16" r="4.6" fill="${['#c98f63','#a87856','#d2a07a','#b98258'][i%4]}" stroke="#3b2a33" stroke-width=".6"/><path d="M-4.6 -16.5 Q-4.6 -22 0 -22 Q4.6 -22 4.6 -16.5Z" fill="${wraps[i%4]}"/></g>`}return s}

/* ===== The three men and the angel ===== */
/* Angels are never pictured as a person. The angel is a cool silver light; when he comes back
   as a poor traveller, the light turns dusty and dim, with a walking staff and a travel bundle. */
function angel(u,x,y,s=1,o={}){
  if(o.guise)return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M14 -10 L19 34" stroke="#7a5534" stroke-width="3" stroke-linecap="round"/><path d="M-26 34 Q-28 20 -18 18 Q-8 20 -10 34Z" fill="#a08a6a" stroke="#5a4a3a" stroke-width=".8"/><path d="M-20 18 q2 -4 5 0" stroke="#5a4a3a" stroke-width="1" fill="none"/><g>${bob(-3,2.6)}<circle r="26" fill="url(#${u}dust)"><animate attributeName="r" values="22;29;22" dur="4.5s" repeatCount="indefinite"/></circle><circle r="7.5" fill="#fffaf0"/>${sparkle(0,0,13,0,'#fffaf0')}</g></g>`;
  return `<g transform="translate(${x} ${y}) scale(${s})"><g>${bob(-5,3.4)}<circle r="44" fill="url(#${u}mal)"><animate attributeName="r" values="36;48;36" dur="4s" repeatCount="indefinite"/></circle><circle r="17" fill="none" stroke="#f4f8ff" stroke-width="1.2" opacity=".6"><animate attributeName="r" values="12;30;12" dur="4s" repeatCount="indefinite"/><animate attributeName="opacity" values=".7;0;.7" dur="4s" repeatCount="indefinite"/></circle><circle r="9" fill="#ffffff"/><g>${rot(0,45,0,0,9)}${sparkle(0,0,22,0,'#f4f8ff')}</g>${sparkle(18,-16,5,1.1,'#ffffff')}${sparkle(-17,12,4,.5,'#e6eeff')}${sparkle(-14,-18,3.5,1.7,'#ffffff')}</g></g>`;
}
/* A little heart and sparkle to say a baby animal is on the way. */
const babySoon=(x,y)=>`<g transform="translate(${x} ${y})"><g>${bob(-3,1.6)}<path d="M0 5 C-8 -1 -8 -8 -3.4 -8 C-1.4 -8 0 -6.8 0 -5.4 C0 -6.8 1.4 -8 3.4 -8 C8 -8 8 -1 0 5Z" fill="#f7a8b8" stroke="#a8485a" stroke-width=".8"/></g>${sparkle(9,-8,3,.6,'#fff7d1')}</g>`;
function cow(x,y,s=1,o={}){
  const c=o.c||'#fbf6ec',p=o.patch||'#8a5a3a',d=shade(c,-.18),ln='#3b2a33';
  const leg=(lx,back)=>`<path d="M${lx} -24 L${lx} -2 L${lx+6} -2 L${lx+6} -24Z" fill="${back?d:c}" stroke="${ln}" stroke-width=".8"/><rect x="${lx-.5}" y="-4" width="7" height="4" rx="1.5" fill="#5a4a3a"/>`;
  const belly=o.baby?`<path d="M-20 -22 Q2 -4 20 -22Z" fill="${c}" stroke="${ln}" stroke-width=".8"/>`:'';
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})"><ellipse cx="2" cy="0" rx="32" ry="3.6" fill="#000" opacity=".14"/>${leg(-22,1)}${leg(10,1)}<path d="M-30 -30 Q-38 -26 -36 -14" stroke="${c}" stroke-width="3" fill="none" stroke-linecap="round">${rot(-10,10,-30,-30,2.2)}</path><circle cx="-36" cy="-12" r="3" fill="${p}"/>${leg(-14)}${leg(17)}<g>${o.graze?'':bob(-1,2.4)}<rect x="-32" y="-46" width="58" height="26" rx="13" fill="${c}" stroke="${ln}" stroke-width="1"/>${belly}<path d="M-18 -46 Q-8 -40 -14 -30 Q-24 -28 -26 -38 Q-26 -44 -18 -46Z M4 -46 Q14 -42 10 -34 Q2 -32 0 -40Z" fill="${p}"/><path d="M-30 -24 Q0 -18 24 -24" stroke="${d}" stroke-width="2" fill="none" opacity=".6"/><g transform="${o.graze?'rotate(28 26 -40)':''}"><path d="M28 -50 q-2 -7 3 -8 M42 -50 q2 -7 -3 -8" stroke="#e9d9b0" stroke-width="2.6" fill="none" stroke-linecap="round"/><ellipse cx="25" cy="-46" rx="6" ry="3" fill="${p}" transform="rotate(-20 25 -46)"/><rect x="24" y="-52" width="22" height="22" rx="10" fill="${c}" stroke="${ln}" stroke-width="1"/><ellipse cx="38" cy="-33" rx="10" ry="6.5" fill="#f4b6b0" stroke="${ln}" stroke-width=".8"/><circle cx="35" cy="-33" r="1.2" fill="${ln}"/><circle cx="41" cy="-33" r="1.2" fill="${ln}"/><ellipse cx="38" cy="-44" rx="2.4" ry="3" fill="#2a1d17"/><circle cx="38.8" cy="-45.2" r=".9" fill="#fff"/><ellipse cx="44" cy="-40" rx="2.4" ry="1.3" fill="#f28a8a" opacity=".6"/></g></g></g>`;
}
function sheep(x,y,s=1,o={}){
  const c=o.c||'#fffaf0',f=o.face||'#4a3a3a',d=shade(c,-.12),k=o.baby?1.12:1;
  const fluff=[[-14,-24,9],[-4,-30,10],[8,-29,9],[16,-22,8],[-16,-14,8],[-4,-14,10],[10,-14,9]].map(([a,b,r])=>`<circle cx="${a}" cy="${b}" r="${(r*k).toFixed(1)}" fill="${c}" stroke="#7a6a5a" stroke-width=".7"/>`).join('');
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})"><ellipse cx="0" cy="0" rx="22" ry="3" fill="#000" opacity=".14"/>${[-12,-4,6,12].map(lx=>`<rect x="${lx}" y="-10" width="3.6" height="10" rx="1.5" fill="${f}"/>`).join('')}<g>${o.graze?'':bob(-1,1.8)}${fluff}<path d="M-18 -20 Q-4 -12 14 -18" stroke="${d}" stroke-width="2" fill="none"/><g transform="${o.graze?'rotate(30 20 -22)':''}"><ellipse cx="18" cy="-24" rx="6" ry="3" fill="${f}" transform="rotate(-25 18 -24)"/><ellipse cx="25" cy="-22" rx="7" ry="8.5" fill="${f}"/><circle cx="22" cy="-30" r="4.5" fill="${c}"/><circle cx="27" cy="-31" r="4" fill="${c}"/><ellipse cx="27" cy="-23" rx="1.8" ry="2.3" fill="#fff"/><circle cx="27.5" cy="-23.4" r="1.1" fill="#1d1414"/><ellipse cx="29" cy="-18" rx="2" ry="1.1" fill="#f28a8a" opacity=".65"/></g></g></g>`;
}
/* A herd spread over a valley: farther animals are smaller and drawn first. */
function herd(fn,x1,x2,y1,y2,n,seed,k=1){const r=rng(seed),a=[];for(let i=0;i<n;i++){const y=y1+r()*(y2-y1);a.push([x1+r()*(x2-x1),y,r()>.5,r()>.6])}
  return a.sort((p,q)=>p[1]-q[1]).map(([x,y,f,g])=>fn(+x.toFixed(1),+y.toFixed(1),+(k*(.55+.45*(y-y1)/(y2-y1||1))).toFixed(2),{flip:f,graze:g})).join('')}
const fence=(x1,x2,y,c='#a07a52')=>{let s=`<path d="M${x1} ${y-12} H${x2} M${x1} ${y-5} H${x2}" stroke="${c}" stroke-width="2.4"/>`;for(let x=x1;x<=x2;x+=18)s+=`<rect x="${x-2}" y="${y-17}" width="4" height="18" rx="1" fill="${shade(c,-.15)}"/>`;return s};

/* ===== Prophet Ayyub the patient ===== */
/* Prophet Ayyub is never pictured. Like Yunus he is a soft, warm light (nur); while he is ill the light is
   smaller and paler, but it never goes out. */
/* A simple shade of palm trunks and fronds, where Ayyub rests and prays on his mat. */
function shelter(x,y,s=1,night){const post=night?'#3a2e4a':'#7a5534',roof=night?'#3e4a5e':'#8a9a52',frond=night?'#34405a':'#6f8a3e';
  return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-48 0 V-60 M48 0 V-60 M-18 0 V-66 M18 0 V-66" stroke="${post}" stroke-width="5" stroke-linecap="round"/><path d="M-62 -58 Q0 -80 62 -58 L58 -50 Q0 -70 -58 -50Z" fill="${roof}"/>${[...Array(13)].map((_,i)=>{const fx=-56+i*9.3,fy=-56-Math.sin(i/12*Math.PI)*12;return `<path d="M${fx.toFixed(1)} ${fy.toFixed(1)} q${i%2?3:-3} 8 ${i%2?1:-1} ${12+(i%3)*3}" stroke="${frond}" stroke-width="3" fill="none" stroke-linecap="round"/>`}).join('')}<rect x="-38" y="-6" width="76" height="8" rx="2" fill="${night?'#6a3a4a':'#b5584a'}"/><path d="M-33 -2 H33" stroke="${night?'#a8846a':'#f2c86b'}" stroke-width="1.6" stroke-dasharray="5 4"/></g>`}
/* A tree with no leaves left, for the long, hard days. */
const bareTree=(x,y,s=1,c='#6a5544')=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0 Q-4 -36 2 -70 M1 -46 L-18 -64 M0 -56 L20 -80 M2 -70 L-8 -88 M12 -70 L24 -72" stroke="${c}" stroke-width="5" fill="none" stroke-linecap="round"/></g>`;
/* Soft grey drizzle falling slantwise. */
function drizzle(n,seed){const r=rng(seed);let s='';for(let i=0;i<n;i++){const x=r()*420,y=r()*220,d=(1.2+r()*.8).toFixed(2);s+=`<path d="M${x.toFixed(1)} ${y.toFixed(1)} l-3 10" stroke="#eef0fa" stroke-width="1.2" stroke-linecap="round" opacity=".5"><animateTransform attributeName="transform" type="translate" values="0 -30;-8 50" dur="${d}s" repeatCount="indefinite"/></path>`}return s}
/* Rings spreading out over the ground where Ayyub taps it with his foot. */
const ringPulse=(x,y,c='#fff3c4')=>[0,.8,1.6].map(b=>`<ellipse cx="${x}" cy="${y}" rx="4" ry="1.4" fill="none" stroke="${c}" stroke-width="2.4" opacity="0"><animate attributeName="rx" values="4;64" dur="2.4s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="ry" values="1.4;16" dur="2.4s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values=".9;0" dur="2.4s" begin="${b}s" repeatCount="indefinite"/></ellipse>`).join('');
/* Dry, cracked earth. */
const cracks=(seed,y1,y2,c='#a8794a')=>{const r=rng(seed);let s='';for(let i=0;i<9;i++){let x=20+r()*360,y=y1+r()*(y2-y1),d=`M${x.toFixed(0)} ${y.toFixed(0)}`;for(let k=0;k<4;k++){x+=6+r()*12;y+=r()*8-4;d+=` L${x.toFixed(0)} ${y.toFixed(0)}`}s+=`<path d="${d}" stroke="${c}" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`}return s};
/* The cool spring that flowed when Ayyub struck the ground: a bubbling spout, ripples and a clear pool. */
function springWater(x,y,s=1){const r=rng(5);let drops='';for(let i=0;i<10;i++){const side=i%2?1:-1,dx=side*(14+r()*30),d=(1.1+r()*.7).toFixed(2),b=(r()*1.4).toFixed(2);drops+=`<circle r="${(1.6+r()*1.6).toFixed(1)}" fill="#e6f8ff" opacity="0"><animate attributeName="cx" values="0;${(dx*.6).toFixed(1)};${dx.toFixed(1)}" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="cy" values="-40;-58;-2" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" dur="${d}s" begin="${b}s" repeatCount="indefinite"/></circle>`}
  return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse rx="74" ry="17" fill="#2f7fb0"/><ellipse cy="-1" rx="70" ry="14.5" fill="#5fb6e2"/><ellipse cy="-2" rx="48" ry="8" fill="#9ad8f4" opacity=".8"/>${[0,1,2].map(b=>`<ellipse rx="6" ry="1.6" fill="none" stroke="#e6f8ff" stroke-width="1.6" opacity="0"><animate attributeName="rx" values="6;62" dur="3s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="ry" values="1.6;12" dur="3s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values=".9;0" dur="3s" begin="${b}s" repeatCount="indefinite"/></ellipse>`).join('')}<g><animateTransform attributeName="transform" type="scale" values="1 1;1 1.14;1 .94;1 1" dur="1.6s" repeatCount="indefinite"/><path d="M-7 0 Q-6 -30 -2 -44 Q0 -50 2 -44 Q6 -30 7 0Z" fill="#bfe8ff" opacity=".9"/><path d="M-2 -2 Q-2 -28 0 -42" stroke="#ffffff" stroke-width="2" fill="none" opacity=".8"/><path d="M0 -44 Q-14 -50 -22 -30 M0 -44 Q14 -50 22 -30" stroke="#bfe8ff" stroke-width="3" fill="none" stroke-linecap="round" opacity=".85"/></g>${drops}${[[-56,-4],[52,-6],[-30,6],[34,5]].map(([a,b])=>`<path d="M${a} ${b} l-3 -12 M${a} ${b} l3 -11 M${a} ${b} l0 -14" stroke="#4f9a44" stroke-width="2" stroke-linecap="round"/>`).join('')}</g>`}
/* A little cup of water beside a bed. */
const cup=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-7 -14 H7 L5 0 H-5Z" fill="#c8794a" stroke="#6b3a22" stroke-width="1"/><ellipse cy="-14" rx="7" ry="2" fill="#7fc8ec"/></g>`;
/* ================= Scenes ================= */
/* ===== The guest and the dark lamp ===== */
/* The Prophet Muhammad ﷺ is never pictured, not even as a light: his pages show the guest, the companions and the homes. */
/* A little clay oil lamp. Lit, its flame flickers and glows; put out, a thin curl of smoke rises. */
function lamp(u,x,y,s=1,lit=true){return `<g transform="translate(${x} ${y}) scale(${s})">${lit?`<circle cy="-12" r="40" fill="url(#${u}lamp)"><animate attributeName="r" values="36;44;36" dur="2.4s" repeatCount="indefinite"/></circle>`:`<path d="M10 -10 q-5 -8 0 -14 t0 -14 t0 -14" stroke="#c9c3d9" stroke-width="1.6" fill="none" stroke-linecap="round" opacity=".7"><animate attributeName="opacity" values="0;.7;0" dur="3.2s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 4;2 -6" dur="3.2s" repeatCount="indefinite"/></path>`}<path d="M-16 -4 Q-16 -12 0 -12 Q12 -12 16 -8 L22 -11 Q22 -6 16 -3 Q10 2 0 2 Q-16 2 -16 -4Z" fill="#c8794a" stroke="#6b3a22" stroke-width="1"/><path d="M-16 -4 Q-16 2 0 2 Q-8 0 -10 -6Z" fill="#a85e36"/><ellipse cx="-2" cy="-11" rx="6" ry="1.6" fill="#5a3020"/><path d="M-13 -9 Q-6 -12 2 -11.5" stroke="#f0b483" stroke-width="1.3" fill="none" stroke-linecap="round"/>${lit?`<g transform="translate(19 -13)"><path d="M0 0 Q-5 -6 0 -16 Q5 -6 0 0Z" fill="#ffb53b"><animateTransform attributeName="transform" type="scale" values="1 1;.85 1.15;1 .9;1 1" dur="1.2s" repeatCount="indefinite"/></path><path d="M0 -1 Q-2.4 -4 0 -9 Q2.4 -4 0 -1Z" fill="#fff4c9"/></g>`:''}</g>`}
/* A plain bowl, empty or with a warm meal in it, and a clay water jug. */
const bowl=(x,y,s=1,full)=>`<g transform="translate(${x} ${y}) scale(${s})">${full?`<ellipse cx="0" cy="-8" rx="14" ry="4.5" fill="#e0a44a"/><circle cx="-5" cy="-9" r="2.6" fill="#f2d07a"/><circle cx="4" cy="-10" r="2.2" fill="#b5584a"/><circle cx="1" cy="-7" r="2" fill="#f2d07a"/>${rising(3,7,0,-12,14,22,'#fff6e6')}`:`<ellipse cx="0" cy="-8" rx="14" ry="4.5" fill="#6b4a32"/>`}<path d="M-16 -8 Q-14 4 0 4 Q14 4 16 -8Z" fill="#a8703e" stroke="#5a3b24" stroke-width="1"/><path d="M-12 -4 Q-6 1 2 1" stroke="#d29a62" stroke-width="1.6" fill="none" stroke-linecap="round"/></g>`;
const jug=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-6 -34 h12 l-1 5 Q14 -24 14 -12 Q14 0 0 0 Q-14 0 -14 -12 Q-14 -24 -5 -29Z" fill="#c8794a" stroke="#6b3a22" stroke-width="1"/><path d="M-14 -12 Q-14 0 0 0 Q-8 -4 -9 -16 Q-9 -24 -5 -29Q-14 -24 -14 -12Z" fill="#a85e36"/><path d="M13 -24 q8 2 4 12" stroke="#a85e36" stroke-width="2.6" fill="none"/><ellipse cx="0" cy="-34" rx="6" ry="1.6" fill="#9fe0ff"/><path d="M-7 -20 h14" stroke="#f0b483" stroke-width="1.4"/></g>`;
/* Children asleep under a quilt, with little z's floating up. */
function sleepers(x,y,s=1){const kid=(dx,c,hair)=>`<g transform="translate(${dx} 0)"><ellipse cx="-14" cy="-8" rx="9" ry="5" fill="#f4ead2"/><circle cx="-14" cy="-13" r="7.5" fill="#c98f63" stroke="#3b2a33" stroke-width=".9"/><path d="M-21.5 -12 Q-22 -22 -13 -21 Q-6 -21 -6.5 -13 Q-11 -17 -21.5 -12Z" fill="${hair}"/><path d="M-10 -3 Q-8 -17 10 -15 Q26 -14 26 -3Z" fill="${c}" stroke="#3b2a33" stroke-width="1"/><path d="M-6 -9 Q8 -13 22 -8" stroke="${shade(c,.35)}" stroke-width="1.4" fill="none" stroke-dasharray="3 3"/></g>`;
  const z=(zx,d)=>`<text x="${zx}" y="-24" font-family="Young Serif, Georgia, serif" font-size="9" font-weight="700" fill="#cfd6ff" opacity="0">z<animate attributeName="opacity" values="0;.9;0" dur="3s" begin="${d}s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 0;6 -16" dur="3s" begin="${d}s" repeatCount="indefinite"/></text>`;
  return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-28" y="-4" width="96" height="6" rx="3" fill="#b5584a"/>${kid(0,'#e8a06a','#3a2a22')}${kid(38,'#7fb6d8','#5a3a2a')}${z(-12,0)}${z(26,1.4)}</g>`}
/* The room of the Ansari's little home: mud walls, a palm-beam ceiling, a rug and one small window. */
